// Personas: profiles and explicit review reuse the existing authenticated gateway.
const PERSON_FIELDS={nombre:'Nombre',aliases:'Alias',organizacion:'Organización',funcion:'Función',relacion_conmigo:'Relación conmigo',ambitos:'Ámbitos',contactos_profesionales:'Contactos profesionales',notas_manuales:'Notas manuales',tipo:'Clasificación'};
const PERSON_AMBITOS=['Trabajo','Apostólico','Colegios','Formación'];
const PERSON_RELATIONS=['participó en','mencionado en','trabaja con','vinculado al proyecto','fuente','relacionado con','referencia'];
function newPeopleState(){return {items:[],total:0,page:1,perPage:12,q:'',ambito:'',view:'',loading:false,error:null,selected:null,tab:'ficha',editing:false,preview:false,form:null,base:null,requestId:null,newOpen:false,newName:'',newRequest:null,changes:[],authorized:{},targets:[],targetId:'',relation:'relacionado con',linkRequest:null,linkPreview:false,conflict:false,busy:false,proposing:false,proofId:'',quote:'',questions:''};}
async function peopleRequest(path,options={}){
  const response=await api(path,options);
  const data=await response.json().catch(()=>({}));
  if(!response.ok){const error=new Error(typeof data.detail==='string'?data.detail:response.status===422?'Revisá los campos y la evidencia.':data.error||'No se pudo completar la operación.');error.status=response.status;throw error;}
  return data;
}
function peopleError(error){S.people.error=error.message;S.people.conflict=error.status===409;}
async function loadPeople(){
  const p=S.people;const request=(p.listRequest||0)+1;p.listRequest=request;p.loading=true;p.error=null;render();
  try{const query=new URLSearchParams({q:p.q,page:p.page,per_page:p.perPage});if(p.ambito)query.set('ambito',p.ambito);if(p.view)query.set('view',p.view);const result=await peopleRequest('/people/directory?'+query);if(request!==p.listRequest)return;p.items=result.results;p.total=result.total;}
  catch(error){if(request===p.listRequest)peopleError(error);}finally{if(request===p.listRequest){p.loading=false;render();}}
}
function filterPeople(key,value){const p=S.people;p[key]=value;p.page=1;loadPeople();}
async function openPerson(id){
  const p=S.people;const request=(p.profileRequest||0)+1;p.profileRequest=request;p.loading=true;p.error=null;p.conflict=false;p.editing=false;p.preview=false;render();
  try{const profile=await peopleRequest('/people/'+encodeURIComponent(id)+'/profile');if(request!==p.profileRequest)return;p.selected=profile;const changes=await peopleRequest('/people/changes?note_id='+encodeURIComponent(id)+'&per_page=100');if(request!==p.profileRequest)return;p.changes=changes.results;p.authorized={};p.tab='ficha';p.linkPreview=false;p.targetId='';}
  catch(error){if(request===p.profileRequest)peopleError(error);}finally{if(request===p.profileRequest){p.loading=false;render();}}
}
function closePerson(){const p=S.people;p.profileRequest=(p.profileRequest||0)+1;p.selected=null;p.editing=false;p.conflict=false;p.error=null;loadPeople();}
function personMissing(value){return value==null||value===''||Array.isArray(value)&&!value.length||typeof value==='object'&&!Object.keys(value).length;}
function personText(value){return personMissing(value)?'Pendiente':Array.isArray(value)?value.join(' · '):typeof value==='object'?Object.entries(value).map(([k,v])=>k.replaceAll('_',' ')+': '+v).join(' · '):String(value);}
function personForm(profile){const f=structuredClone(profile.fields);f.aliases=f.aliases||[];f.ambitos=f.ambitos||[];f.contactos_profesionales=f.contactos_profesionales||{};f.confirm_review=!!profile.metadata.revisado;return f;}
function startPersonEdit(proposing=false){const p=S.people;p.editing=true;p.proposing=proposing;p.form=personForm(p.selected);p.base=structuredClone(p.selected.fields);p.requestId=crypto.randomUUID();p.preview=false;p.error=null;p.proofId='';p.quote='';p.questions='';if(proposing)loadPeopleTargets();render();}
function personField(key,value){const p=S.people;p.form[key]=value;p.preview=false;p.requestId=crypto.randomUUID();}
function togglePersonAmbito(value,on){let a=S.people.form.ambitos||[];personField('ambitos',on?[...new Set([...a,value])]:a.filter(v=>v!==value));}
function personDiff(){const p=S.people;const result={};for(const key of Object.keys(PERSON_FIELDS)){let value=p.form[key];if(typeof value==='string')value=value.trim()||null;if(JSON.stringify(value??null)!==JSON.stringify(p.base[key]??null))result[key]=value;}return result;}
async function createPerson(){
  const p=S.people;if(p.busy)return;if(!p.newName.trim()){p.error='Escribí el nombre de la persona.';render();return;}
  p.busy=true;p.error=null;p.newRequest=p.newRequest||crypto.randomUUID();render();
  try{const result=await peopleRequest('/people/drafts',{method:'POST',body:JSON.stringify({nombre:p.newName.trim(),request_id:p.newRequest})});p.newOpen=false;p.newName='';p.newRequest=null;await openPerson(result.id);if(result.needs_identity_review)p.error='Se encontró una ficha existente. Revisá su identidad; no se modificó ni se fusionó.';}
  catch(error){peopleError(error);}finally{p.busy=false;render();}
}
async function savePerson(){
  const p=S.people;if(p.busy)return;if(!p.preview){p.preview=true;render();return;}
  const changes=personDiff();if(!Object.keys(changes).length&&p.form.confirm_review)changes.nombre=p.selected.fields.nombre;
  if(!Object.keys(changes).length){p.error='No hay cambios para guardar.';render();return;}
  p.busy=true;p.error=null;render();
  try{
    let body={request_id:p.requestId,revision:p.selected.revision,fields:changes};
    if(p.proposing){if(!p.proofId||!p.quote.trim())throw new Error('Elegí una fuente real e indicá la cita literal.');body.evidence=Object.keys(changes).map(field=>({field,source_id:p.proofId,quote:p.quote}));body.questions=p.questions.trim()?[p.questions.trim()]:[];await peopleRequest('/people/'+encodeURIComponent(p.selected.id)+'/proposals',{method:'POST',body:JSON.stringify(body)});}
    else {body.confirm_review=p.form.confirm_review;await peopleRequest('/people/'+encodeURIComponent(p.selected.id)+'/profile',{method:'PATCH',body:JSON.stringify(body)});}
    await openPerson(p.selected.id);if(body.evidence)p.tab='cambios';
  }catch(error){peopleError(error);}finally{p.busy=false;render();}
}
async function loadPeopleTargets(){
  const p=S.people;const id=p.selected?.id;const targets=[];let page=1;
  try{while(true){const result=await peopleRequest('/notes?per_page=100&page='+page);targets.push(...result.results);if(targets.length>=result.total)break;page++;}if(p.selected?.id!==id)return;p.targets=targets.filter(n=>n.id!==id);render();}
  catch(error){if(p.selected?.id===id){peopleError(error);render();}}
}
function peopleTab(tab){S.people.tab=tab;if(tab==='conexiones')loadPeopleTargets();render();}
async function preparePersonLink(){
  const p=S.people;if(p.busy)return;
  if(!p.targetId){p.error='Elegí un destino real antes de preparar la relación.';render();return;}
  p.busy=true;p.error=null;render();
  try{p.linkTarget=await peopleRequest('/notes/'+encodeURIComponent(p.targetId));p.linkRequest=p.linkRequest||crypto.randomUUID();p.linkPreview=true;}
  catch(error){peopleError(error);}finally{p.busy=false;render();}
}
async function submitPersonLink(action='add',existingIndex=null){
  const p=S.people;if(p.busy)return;
  const selectedId=p.selected.id;let source=selectedId,rev=p.selected.revision,target=p.linkTarget,relation=p.relation;
  if(existingIndex!==null){const edge=p.selected.relations[existingIndex];if(edge.direction==='entrante'){const origin=await peopleRequest('/notes/'+encodeURIComponent(edge.source_id));source=origin.id;rev=origin.revision;target={id:p.selected.id,revision:p.selected.revision};}else{target=await peopleRequest('/notes/'+encodeURIComponent(edge.other_id));}relation=edge.relation;p.linkRequest=crypto.randomUUID();}
  p.busy=true;p.error=null;render();
  try{const command={request_id:p.linkRequest||crypto.randomUUID(),source_id:source,revision:rev,links:[{target_id:target.id,target_revision:target.revision,relation,action}]};
    const proposed=await peopleRequest('/vault/relations/proposals',{method:'POST',body:JSON.stringify(command)});
    await openPerson(selectedId);p.tab='cambios';p.linkRequest=null;
  }catch(error){peopleError(error);}finally{p.busy=false;render();}
}
function authorizePersonChange(id,key,on){const p=S.people;const set=new Set(p.authorized[id]||[]);on?set.add(key):set.delete(key);p.authorized[id]=[...set];render();}
async function reviewPersonChange(index,action){
  const p=S.people;if(p.busy)return;const change=p.changes[index];p.busy=true;p.error=null;render();
  const request=change.reviewRequest||crypto.randomUUID();change.reviewRequest=request;
  try{await peopleRequest('/people/changes/'+encodeURIComponent(change.id)+'/review',{method:'POST',body:JSON.stringify({request_id:request,revision:change.kind==='links'&&change.target_id!==p.selected.id?change.base_revision:p.selected.revision,action,authorized_fields:p.authorized[change.id]||[],expected_kind:change.kind})});await openPerson(p.selected.id);p.tab='cambios';}
  catch(error){peopleError(error);}finally{p.busy=false;render();}
}
async function undoPersonChange(index){
  const p=S.people;if(p.busy)return;const entry=p.selected.history[index];
  if(!confirm('¿Revertir este cambio? Se conservarán las fuentes y no se sobrescribirán ediciones posteriores.'))return;
  p.busy=true;p.error=null;render();
  try{const result=await peopleRequest('/people/history/'+encodeURIComponent(entry.id)+'/undo',{method:'POST',body:JSON.stringify({request_id:crypto.randomUUID(),revision:entry.target_revision||p.selected.revision})});if(result.revision)await openPerson(p.selected.id);else closePerson();}
  catch(error){peopleError(error);}finally{p.busy=false;render();}
}
function renderPeople(){
  const p=S.people;return `<section class="people-workspace">${p.error?`<div role="alert" class="people-alert">${esc(p.error)}${p.conflict&&p.selected?`<p>Los cambios no se guardaron. Compará la ficha actual antes de volver a editar.</p><button class="btn btn-ghost" onclick="openPerson(S.people.selected.id)">Releer ficha y descartar cambios sin guardar</button>`:''}</div>`:''}${p.loading?'<div role="status" class="people-loading">Cargando personas…</div>':''}${p.selected?renderPersonProfile():renderPeopleDirectory()}</section>`;
}
function renderPeopleDirectory(){
  const p=S.people;const views=[['','Todas'],['incomplete','Por completar'],['pending','Cambios pendientes'],['unconnected','Sin conexiones'],['duplicates','Posibles duplicados'],['no_outgoing','Sin enlaces salientes']];
  return `<header class="people-header"><div><div class="people-eyebrow">TU RED DE CONOCIMIENTO</div><h1>Personas</h1><p>Una ficha por persona. Sus ámbitos, fuentes y vínculos en un solo lugar.</p></div><button class="btn btn-primary" onclick="S.people.newOpen=!S.people.newOpen;render()">+ Nueva persona</button></header>
  ${p.newOpen?`<form class="people-new" onsubmit="event.preventDefault();createPerson()"><label for="person-new-name">Nombre de la persona</label><div class="people-inline"><input id="person-new-name" class="fi" required maxlength="200" value="${esc(p.newName)}" oninput="S.people.newName=this.value;S.people.newRequest=null" placeholder="Sólo el nombre para empezar"><button class="btn btn-primary" type="submit" ${p.busy?'disabled':''}>Crear ficha mínima</button></div><p>Los demás datos quedarán pendientes. Se comprobarán fichas existentes antes de crear.</p></form>`:''}
  <div class="people-controls"><form onsubmit="event.preventDefault();filterPeople('q',document.getElementById('people-query').value)"><label class="sr-only" for="people-query">Buscar por nombre, alias u organización</label><input id="people-query" type="search" class="fi" value="${esc(p.q)}" placeholder="Buscar por nombre, alias u organización"><button class="btn btn-ghost" type="submit">Buscar</button></form><label>Ámbito<select aria-label="Filtrar ámbito" onchange="filterPeople('ambito',this.value)"><option value="">Todos los ámbitos</option>${PERSON_AMBITOS.map(a=>`<option ${p.ambito===a?'selected':''}>${a}</option>`).join('')}</select></label></div>
  <div class="people-tabs" role="group" aria-label="Vistas de personas">${views.map(([key,label])=>`<button class="people-tab ${p.view===key?'active':''}" aria-pressed="${p.view===key}" onclick="filterPeople('view','${key}')">${label}</button>`).join('')}</div>
  <div class="people-results"><span>${p.total} ${p.total===1?'persona':'personas'}</span><span>Datos declarados · sin inferir identidades</span></div>
  <div class="people-grid">${p.items.map((n,index)=>`<article class="people-card"><div class="people-card-top"><div class="people-avatar" aria-hidden="true">${esc((n.fields.nombre||n.title).slice(0,1))}</div><span class="people-status ${n.metadata.revisado?'reviewed':''}">${n.metadata.revisado?'Revisada':'Por revisar'}</span></div><h2><button onclick="openPerson(S.people.items[${index}].id)">${esc(n.fields.nombre||n.title)}</button></h2><p class="people-organization">${esc(n.fields.organizacion||'Organización pendiente')}</p><p class="people-role">${esc(n.fields.funcion||'Función pendiente')}</p><div class="people-chips">${(n.fields.ambitos||[]).map(a=>`<span>${esc(a)}</span>`).join('')||'<span>Ámbito pendiente</span>'}</div><div class="people-card-footer"><span>${n.incoming_count+n.outgoing_count} conexiones</span>${n.pending_changes?`<span class="people-pending">${n.pending_changes} ${n.pending_changes===1?'cambio pendiente':'cambios pendientes'}</span>`:n.pending_fields.length?`<span>${n.pending_fields.length} ${n.pending_fields.length===1?'dato por completar':'datos por completar'}</span>`:'<span>Ficha completa</span>'}</div>${n.classification_warning?`<p class="people-warning">${esc(n.classification_warning)}</p>`:''}</article>`).join('')||(!p.loading?'<div class="people-empty">No hay personas en esta vista. Podés cambiar los filtros o crear una ficha mínima.</div>':'')}</div>
  <footer class="people-pagination"><button class="btn btn-ghost" ${p.page<=1?'disabled':''} onclick="S.people.page--;loadPeople()">Anterior</button><span>Página ${p.page} de ${Math.max(1,Math.ceil(p.total/p.perPage))}</span><button class="btn btn-ghost" ${p.page*p.perPage>=p.total?'disabled':''} onclick="S.people.page++;loadPeople()">Siguiente</button></footer>`;
}
function renderPersonProfile(){
  const p=S.people,n=p.selected;if(p.editing)return renderPersonEditor();
  const tabs=[['ficha','Ficha'],['conexiones','Conexiones'],['cambios','Cambios pendientes'],['historial','Historial']];
  return `<button class="btn-back" onclick="closePerson()">‹ Personas</button><header class="people-header"><div><div class="people-eyebrow">FICHA DE PERSONA</div><h1>${esc(n.fields.nombre||n.title)}</h1><p>${esc(n.fields.organizacion||'Organización pendiente')} · ${esc(n.fields.funcion||'Función pendiente')}</p></div><button class="btn btn-primary" onclick="startPersonEdit(${n.metadata.fuente_inmutable?'true':'false'})">${n.metadata.fuente_inmutable?'Preparar corrección separada':'Editar ficha'}</button></header>
  <div class="people-profile-status"><span class="people-status ${n.metadata.revisado?'reviewed':''}">${n.metadata.revisado?'Datos revisados':'Datos pendientes de revisión'}</span><span>Última revisión: ${esc(n.last_review||'Pendiente')}</span><span>Origen: ${esc(n.change_origin?.includes('asistente')?'Asistente':n.change_origin?.includes('manual')?'Manual':n.change_origin||'Existente')}</span></div>
  <div class="people-tabs" role="tablist">${tabs.map(([key,label])=>`<button role="tab" aria-selected="${p.tab===key}" class="people-tab ${p.tab===key?'active':''}" onclick="peopleTab('${key}')">${label}${key==='cambios'&&p.changes.length?` (${p.changes.length})`:''}</button>`).join('')}</div>
  ${p.tab==='conexiones'?renderPersonConnections():p.tab==='cambios'?renderPersonChanges():p.tab==='historial'?renderPersonHistory():renderPersonFacts()}`;
}
function renderPersonFacts(){
  const n=S.people.selected;return `<div class="people-profile-grid"><section class="people-panel"><h2>Datos de la ficha</h2><dl class="people-facts">${Object.entries(PERSON_FIELDS).filter(([k])=>k!=='tipo').map(([key,label])=>`<div><dt>${label}</dt><dd class="${personMissing(n.fields[key])?'pending':''}">${esc(personText(n.fields[key]))}${(n.field_sources[key]||[]).map(proof=>`<small>Fuente: ${esc(proof.path)} · ${esc(proof.fecha||'Sin fecha registrada')}</small>`).join('')}</dd></div>`).join('')}</dl><p class="people-original-path">Ficha existente: ${esc(n.path)}</p></section><aside><section class="people-panel"><h2>Conexiones verificadas</h2><div class="people-stat-row"><strong>${n.incoming_count}</strong><span>enlaces entrantes</span><strong>${n.outgoing_count}</strong><span>enlaces salientes</span></div><p>Una mención no confirma participación ni vínculo laboral.</p><button class="btn btn-ghost" onclick="peopleTab('conexiones')">Ver destinos y relaciones</button></section><section class="people-panel"><h2>Por revisar</h2><p>${n.pending_changes} propuestas pendientes, separadas de los datos de la ficha.</p>${n.classification_warning?`<p class="people-warning">${esc(n.classification_warning)}</p><button class="btn btn-ghost" onclick="startPersonEdit()">Revisar clasificación manualmente</button>`:''}${n.possible_duplicates.map(d=>`<p class="people-warning">Posible coincidencia: ${esc(d.title)}<small>${esc(d.path)} · No se fusionó.</small></p>`).join('')}${n.broken_links.length?`<p class="people-warning">Enlaces rotos: ${n.broken_links.map(esc).join(', ')}</p>`:''}${n.ambiguous_links.length?`<p class="people-warning">Destinos ambiguos: ${n.ambiguous_links.map(esc).join(', ')}</p>`:''}</section></aside></div>${n.original_content?`<details class="people-panel"><summary>Contenido original existente · conservado</summary><pre class="people-original">${esc(n.original_content)}</pre></details>`:''}`;
}
function renderPersonEditor(){
  const p=S.people,f=p.form;const fields=['nombre','organizacion','funcion','relacion_conmigo'];
  return `<button class="btn-back" onclick="S.people.editing=false;render()">‹ Volver a la ficha</button><header class="people-header"><div><div class="people-eyebrow">${p.proposing?'CORRECCIÓN SEPARADA':'EDICIÓN MANUAL'}</div><h1>${p.proposing?'Preparar propuesta':'Completar ficha'}</h1><p>Completá sólo los datos que conocés. La fuente original se conserva.</p></div></header>
  <form onsubmit="event.preventDefault();savePerson()" class="people-editor"><div class="people-form-grid">${fields.map(key=>`<label for="person-field-${key}">${PERSON_FIELDS[key]}${key==='nombre'?' *':''}<input class="fi" id="person-field-${key}" ${key==='nombre'?'required':''} maxlength="${key==='nombre'?200:key==='relacion_conmigo'?1000:300}" value="${esc(f[key]||'')}" oninput="personField('${key}',this.value)"></label>`).join('')}<label for="person-field-aliases">Alias separados por coma<input class="fi" id="person-field-aliases" value="${esc(f.aliases.join(', '))}" oninput="personField('aliases',this.value.split(',').map(s=>s.trim()).filter(Boolean))"></label><label>Clasificación<select aria-label="Clasificación" onchange="personField('tipo',this.value)">${['persona','idea','recurso','nota'].map(t=>`<option ${f.tipo===t?'selected':''}>${t}</option>`).join('')}</select></label></div>
  <fieldset><legend>Ámbitos · puede participar en varios</legend><div class="people-checkboxes">${PERSON_AMBITOS.map(a=>`<label><input type="checkbox" ${f.ambitos.includes(a)?'checked':''} onchange="togglePersonAmbito('${a}',this.checked)">${a}</label>`).join('')}</div></fieldset>
  <fieldset><legend>Contactos profesionales opcionales</legend><div class="people-form-grid">${[['email_profesional','Email profesional'],['telefono_profesional','Teléfono profesional'],['perfil_profesional','Perfil profesional']].map(([key,label])=>`<label>${label}<input class="fi" maxlength="500" ${key==='email_profesional'?'type="email"':''} value="${esc(f.contactos_profesionales[key]||'')}" oninput="S.people.form.contactos_profesionales['${key}']=this.value;S.people.preview=false;S.people.requestId=crypto.randomUUID()"></label>`).join('')}</div><p>No incluyas credenciales ni información personal reservada.</p></fieldset>
  <label for="person-field-notas">Notas manuales<textarea class="fi" id="person-field-notas" maxlength="20000" oninput="personField('notas_manuales',this.value)">${esc(f.notas_manuales||'')}</textarea></label>
  ${p.proposing?`<fieldset><legend>Evidencia de la propuesta</legend><label>Fuente<select aria-label="Fuente de la propuesta" onchange="S.people.proofId=this.value;S.people.preview=false"><option value="">Elegir fuente existente</option>${p.targets.map(n=>`<option value="${esc(n.id)}" ${p.proofId===n.id?'selected':''}>${esc(n.title)} — ${esc(n.path)}</option>`).join('')}</select></label><label>Cita literal<textarea class="fi" oninput="S.people.quote=this.value;S.people.preview=false">${esc(p.quote)}</textarea></label><label>Pregunta pendiente<input class="fi" value="${esc(p.questions)}" oninput="S.people.questions=this.value;S.people.preview=false"></label></fieldset>`:`<label class="people-check"><input type="checkbox" ${f.confirm_review?'checked':''} onchange="S.people.form.confirm_review=this.checked;S.people.preview=false">Confirmé manualmente los datos de esta ficha</label>`}
  ${p.preview?`<section class="people-preview"><h2>Vista previa de cambios</h2>${Object.entries(personDiff()).map(([key,value])=>`<div><strong>${PERSON_FIELDS[key]}</strong><p class="people-before">Anterior: ${esc(personText(p.base[key]))}</p><p>Nuevo: ${esc(personText(value))}</p></div>`).join('')||'<p>Sin cambios de campos. Podés confirmar su revisión.</p>'}<p>El contenido original no se reescribe. ${p.proposing?'Se guardará como propuesta pendiente.':''}</p></section>`:''}
  <div class="people-actions"><button class="btn btn-primary" type="submit" ${p.busy?'disabled':''}>${p.busy?'Guardando…':p.preview?p.proposing?'Guardar propuesta pendiente':'Confirmar y guardar cambios':'Ver vista previa'}</button><button class="btn btn-ghost" type="button" onclick="S.people.editing=false;render()">Cancelar</button></div></form>`;
}
function renderPersonConnections(){
  const p=S.people,n=p.selected;return `<section class="people-panel"><h2>Agregar una relación</h2><p>Seleccioná el destino real y el tipo. Primero quedará como propuesta para revisión.</p><div class="people-form-grid"><label>Destino<select aria-label="Destino real de la relación" onchange="S.people.targetId=this.value;S.people.linkPreview=false;S.people.linkRequest=null"><option value="">Elegir nota existente</option>${p.targets.map(t=>`<option value="${esc(t.id)}" ${p.targetId===t.id?'selected':''}>${esc(t.title)} — ${esc(t.path)}</option>`).join('')}</select></label><label>Tipo de relación<select aria-label="Tipo de relación" onchange="S.people.relation=this.value;S.people.linkPreview=false;S.people.linkRequest=null">${PERSON_RELATIONS.map(t=>`<option ${p.relation===t?'selected':''}>${t}</option>`).join('')}</select></label></div><button class="btn btn-ghost" ${p.busy?'disabled':''} onclick="preparePersonLink()">Ver destino antes de preparar</button>${p.linkPreview?`<div class="people-preview"><strong>${esc(p.linkTarget.title)}</strong><p>${esc(p.linkTarget.path)}</p><p>Relación: ${esc(p.relation)} · no cambia permisos ni reescribe la fuente.</p><button class="btn btn-primary" ${p.busy?'disabled':''} onclick="submitPersonLink()">Preparar relación pendiente</button></div>`:''}</section>
  <section class="people-panel"><h2>Entrantes y salientes</h2>${n.relations.map((edge,index)=>`<article class="people-relation"><span class="people-status">${edge.direction}</span><div><strong>${esc(edge.relation)} · ${esc(edge.title)}</strong><small>${esc(edge.path)} · ${esc(edge.origin==='legacy'?'Enlace existente':edge.origin==='assistant'?'Asistente':'Manual')}</small>${(edge.reserved_segments||[]).map(s=>`<small>Segmento reservado · ${esc(s.source_reference)} · ${s.start_seconds}–${s.end_seconds} s. Contenido no importado.</small>`).join('')}${edge.evidence?`<blockquote>${esc(edge.evidence.quote)}<small>Fuente: ${esc(edge.evidence.path)} · ${esc(edge.evidence.fecha||'Sin fecha')}</small></blockquote>`:''}</div><button class="btn btn-ghost" onclick="openNote('${esc(edge.other_id)}')">Ver destino</button><button class="btn btn-ghost" onclick="submitPersonLink('remove',${index})">Proponer quitar</button></article>`).join('')||'<p>No hay conexiones visibles. Esto incluye enlaces entrantes y salientes.</p>'}</section>`;
}
function renderPersonChanges(){
  const p=S.people;return `<section class="people-panel"><h2>Sugerencias y preguntas pendientes</h2><p>Estas propuestas no son hechos confirmados. Revisá fuentes y campos antes de aplicarlas.</p>${p.changes.map((c,index)=>{const keys=c.kind==='person'?Object.keys(c.fields):['relations'];const selected=p.authorized[c.id]||[];const canApply=keys.length>0&&keys.every(k=>selected.includes(k));return `<article class="people-change"><div class="people-change-head"><strong>${c.kind==='person'?'Propuesta de ficha':'Propuesta de conexiones'}</strong><span class="people-status">Pendiente · ${esc(c.origin==='assistant'?'Asistente':'Manual')}</span></div>${c.source?`<p>Origen: ${esc(c.source.title)}<small>${esc(c.source.path)}</small></p>`:''}${c.kind==='person'?Object.entries(c.fields).map(([key,value])=>`<p><strong>${PERSON_FIELDS[key]} sugerido:</strong> ${esc(personText(value))}</p>`).join(''):c.links.map(l=>`<p>${esc(l.action==='remove'?'Quitar':'Agregar')} ${esc(l.relation)} → ${esc(l.target?.title||l.target_id)}<small>${esc(l.target?.path||'Identificador: '+l.target_id)}</small></p>`).join('')}${c.evidence.map(proof=>`<blockquote>${esc(proof.quote)}<small>Fuente: ${esc(proof.path)} · ${esc(proof.fecha||'Sin fecha registrada')}</small></blockquote>`).join('')}${(c.questions||[]).map(q=>`<p class="people-question">Pregunta pendiente: ${esc(q)}</p>`).join('')}<fieldset><legend>Autorización explícita</legend>${keys.map(key=>`<label class="people-check"><input type="checkbox" ${selected.includes(key)?'checked':''} onchange="authorizePersonChange('${esc(c.id)}','${key}',this.checked)">Autorizar ${key==='relations'?'las relaciones mostradas':PERSON_FIELDS[key]}</label>`).join('')}</fieldset><div class="people-actions"><button class="btn btn-primary" ${!canApply||p.busy||c.kind==='person'&&p.selected.metadata.fuente_inmutable?'disabled':''} onclick="reviewPersonChange(${index},'apply')">Aplicar cambios autorizados</button><button class="btn btn-ghost" ${p.busy?'disabled':''} onclick="reviewPersonChange(${index},'reject')">Rechazar propuesta</button></div>${c.kind==='person'&&p.selected.metadata.fuente_inmutable?'<p>Fuente inmutable: la corrección queda separada; no se sobrescribe.</p>':''}</article>`;}).join('')||'<div class="people-empty">No hay propuestas pendientes para esta ficha.</div>'}</section>`;
}
function renderPersonHistory(){const p=S.people;return `<section class="people-panel"><h2>Historial de cambios</h2><p>Revertir conserva las fuentes y exige que no haya ediciones posteriores incompatibles.</p>${p.selected.history.map((entry,index)=>`<article class="people-relation"><div><strong>${esc(entry.operation)}</strong><small>${esc(entry.at)} · ${esc(entry.origin==='assistant'?'Asistente':'Manual')} ${entry.undone?'· Revertido':''}</small></div>${!entry.undone?`<button class="btn btn-ghost" ${p.busy?'disabled':''} onclick="undoPersonChange(${index})">Revertir este cambio</button>`:''}</article>`).join('')||'<p>Sin cambios registrados por esta portada.</p>'}</section>`;}
